<?php
session_start(); if(empty($_SESSION['usuario_id'])||($_SESSION['usuario_rol']??'')!=='admin'){header('Location: ../index.php');exit;}
require_once __DIR__.'/../backend/conexion.php';
$estados=['pendiente_cotizacion_envio','pendiente','confirmado','preparando','enviado','entregado','cancelado']; $etiquetasEstado=['pendiente_cotizacion_envio'=>'Envío por cotizar','pendiente'=>'Pendiente','confirmado'=>'Confirmado','preparando'=>'Preparando','enviado'=>'Enviado','entregado'=>'Entregado','cancelado'=>'Cancelado']; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['accion']??'')==='definir_envio'){
 $id=(int)($_POST['id']??0); $costo=filter_var($_POST['costo_envio']??null,FILTER_VALIDATE_FLOAT);
 if($id>0 && $costo!==false && $costo>=0){$q=$pdo->prepare("UPDATE pedidos SET costo_envio=?, total=subtotal+?, estado='pendiente' WHERE id=? AND estado='pendiente_cotizacion_envio'");$q->execute([$costo,$costo,$id]);$msg=$q->rowCount()?'Tarifa de envío confirmada; el pedido ya tiene total actualizado.':'No se encontró un pedido pendiente de cotización.';} else {$msg='Ingresa una tarifa válida.';}
} elseif($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['id']??0);$estado=$_POST['estado']??'';
 if($id>0&&in_array($estado,$estados,true)){
  try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT estado FROM pedidos WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();
   if($old===false)throw new RuntimeException('Pedido no encontrado.');
   if($old==='cancelado'&&$estado!=='cancelado')throw new RuntimeException('Un pedido cancelado no puede reactivarse; crea un nuevo pedido.');
   if($old!=='cancelado'&&$estado==='cancelado'){$d=$pdo->prepare('SELECT producto_id,cantidad FROM pedido_detalles WHERE pedido_id=?');$d->execute([$id]);foreach($d as $r){if($r['producto_id']){$u=$pdo->prepare('UPDATE productos SET stock=stock+? WHERE id=?');$u->execute([$r['cantidad'],$r['producto_id']]);$m=$pdo->prepare("INSERT INTO movimientos_inventario(producto_id,tipo,cantidad,motivo) VALUES(?,'entrada',?,'Reposición por cancelación del pedido #$id')");$m->execute([$r['producto_id'],$r['cantidad']]);}}}
   $u=$pdo->prepare('UPDATE pedidos SET estado=? WHERE id=?');$u->execute([$estado,$id]);$pdo->commit();$msg='Estado del pedido actualizado.';
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg='No se pudo actualizar el pedido: '.$e->getMessage();}
 }
}
if(empty($_SESSION['csrf_pedidos']))$_SESSION['csrf_pedidos']=bin2hex(random_bytes(32));$flash=$_SESSION['pedido_msg']??'';unset($_SESSION['pedido_msg']);
$orders=$pdo->query("SELECT p.*,u.email,CASE WHEN p.estado IS NULL OR TRIM(p.estado)='' THEN 'pendiente' ELSE p.estado END AS estado_visible FROM pedidos p LEFT JOIN usuarios u ON u.id=p.usuario_id ORDER BY p.id DESC")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos</title><style>body{font:15px Arial;background:#f4f6f8;margin:0;color:#222}.top{background:#17191d;color:white;padding:18px 5%}.top a{color:white;margin-right:18px}.wrap{max-width:1200px;margin:28px auto;padding:0 18px}.panel{background:white;padding:18px;border-radius:12px;overflow:auto}table{width:100%;border-collapse:collapse;min-width:950px}td,th{padding:11px;border-bottom:1px solid #eee;text-align:left}input,select,button{padding:8px;border:1px solid #ddd;border-radius:7px}button{background:#e53935;color:white;border:0;cursor:pointer}.ok{color:#187a42}</style></head><body><header class="top"><b>Mi Store · Pedidos</b>　<a href="index.php">Panel</a><a href="reportes.php">Reportes</a><a href="../backend/logout.php">Salir</a></header><main class="wrap"><h1>Gestión de pedidos</h1><?php if($flash):?><p class="ok"><?=htmlspecialchars($flash)?></p><?php endif?><?php if($msg):?><p class="ok"><?=htmlspecialchars($msg)?></p><?php endif?><section class="panel"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Entrega</th><th>Detalle</th><th>Total</th><th>Pago</th><th>Comprobante</th><th>Estado</th><th>Actualizar</th><th>Eliminar</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?><br><small><?=$o['creado_en']?></small></td><td><?=htmlspecialchars($o['cliente_nombre'])?><br><small><?=htmlspecialchars($o['email']??'Invitado')?></small></td><td><?=htmlspecialchars($o['direccion'].', '.$o['distrito'])?></td><td><?php $d=$pdo->prepare('SELECT nombre_producto,cantidad FROM pedido_detalles WHERE pedido_id=?');$d->execute([$o['id']]);foreach($d as $x)echo htmlspecialchars($x['cantidad'].' × '.$x['nombre_producto']).'<br>';?></td><td>S/ <?=number_format($o['total'],2)?></td><td><?=htmlspecialchars($o['metodo_pago'])?><br><?=!empty($o['pago_verificado'])?'Verificado':'Por verificar'?></td><td><?php if(!empty($o['comprobante_pago'])):?><a target="_blank" href="../<?=htmlspecialchars($o['comprobante_pago'])?>">Ver archivo</a><?php else:?>Sin archivo<?php endif?></td><td><strong><?=htmlspecialchars($etiquetasEstado[$o['estado_visible']]??ucfirst(str_replace('_',' ',$o['estado_visible']??'pendiente')))?></strong></td><td><form method="post"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="estado"><?php foreach($estados as $e):?><option value="<?=htmlspecialchars($e)?>" <?=$e===($o['estado_visible']??'pendiente')?'selected':''?>><?=htmlspecialchars($etiquetasEstado[$e]??$e)?></option><?php endforeach?></select><button>Guardar</button></form><?php if(($o['estado_visible']??'')==='pendiente_cotizacion_envio'):?><form method="post" style="margin-top:8px"><input type="hidden" name="accion" value="definir_envio"><input type="hidden" name="id" value="<?=$o['id']?>"><label>Envío S/ <input type="number" name="costo_envio" min="0" step="0.01" required style="width:85px"></label><button>Confirmar tarifa</button></form><?php endif?><?php if(!empty($o['comprobante_pago'])&&!$o['pago_verificado']):?><form method="post" action="verificar_pago.php" style="margin-top:6px"><input type="hidden" name="id" value="<?=$o['id']?>"><button>Verificar pago</button></form><?php endif?></td><td><form method="post" action="../backend/eliminar_pedido.php" onsubmit="return confirm('¿Eliminar definitivamente el pedido #<?=$o['id']?>? Esta acción no se puede deshacer.')"><input type="hidden" name="pedido_id" value="<?=$o['id']?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_pedidos'])?>"><button style="background:#555">🗑 Borrar</button></form></td></tr><?php endforeach?></tbody></table></section></main></body></html>
